mat2 M = mat2(0, -1, 1, 0); //rot(pi/2)

// id: shape:
//  0  square
//  1  line 
//  2  L (upside down)
//  3  T (upside down)
//  4  Z
// Shapes are transformed to have bottom-left corner at (0,0)

vec3 idToColor(int id) {
    if (id == 0) return vec3(240, 240, 0)/255.;
    if (id == 1) return vec3(0, 240, 240)/255.;
    if (id == 2) return vec3(240, 161, 0)/255.;
    if (id == 3) return vec3(161, 0, 240)/255.;
    return vec3(240, 0, 0)/255.;
}

void sub(inout vec2 u, inout int id) 
{
    u += u;

    // Square
    if (id == 0) {
        // could randomly orient according to each shape's symmetry
        //u.x = 4.-u.x; 
        if (u.x<=1.&&u.y<=3.||u.x<=2.&&u.y<=1.) 
            id = 2, u.y = 3.-u.y;
        else if (u.x<=3.&&u.y<=2.||u.y<=1.) 
            id = 4, u.x--;
        else if (u.x<=2.||u.x<=3.&&u.y>3.) 
            id = 3, u = vec2(3,4) - u;
        else 
            id = 3, u = M*u + vec2(-1, 4);     
    }

    // Line
    else if (id == 1) { 
        if (u.y>6.)                       id = 0, u.y -= 6.;
        else if (u.x<=1.&&u.y>3.||u.y>5.) id = 2, u.y -= 3.;
        else if (u.x<=1.||u.y<=1.)        id = 2, u.y = 3. - u.y;
        else                              id = 1, u--;
    }

    // L (upside down)
    else if (id == 2) { 
        if (u.y<=2.)               id = 0;
        else if (u.x<=1.)          id = 1, u.y -= 2.;
        else if (u.x<=3.&&u.y<=5.) id = 2, u -= vec2(1, 2);
        else                       id = 2, u = u*M + vec2(6, -1);
    }

    // T (upside down)
    else if (id == 3) { 
        if (u.y>2.)       id = 0, u -= 2.;
        else if (u.x>1.&&u.x<=5.&&u.y>1.)
                          id = 1, u = u*M + vec2(2,-1);
        else if (u.x<=3.) id = 2, u *= -M,  u.y += 3.;
        else              id = 2, u = u.yx, u.y -= 3.;            
    }

    // Z
    else if (id == 4) { 
        if (u.x>4.)               id = 0, u.x -= 4.;
        else if (u.y>3.)          id = 1, u = vec2(-3,4) - u*M;
        else if (u.x<=3.&&u.y>1.) id = 2, u *= M, u.x += 3.;
        else                      id = 2, u = vec2(4,3) - u;
    }
}

// Boundary distance doesn't work well, maybe <='s and >'s aren't 
// consistent after subshapes are rotated
// (better method might be to calculate sdf to shape borders and 
//  choose id to be closest (or negative) sdf)
float dist(vec2 u, int id) 
{
    float d;
    if (id == 0) {
        return abs(length(u-1.) - .5);
    }
    if (id == 1) {
        return seg(u, vec2(.5, .5), vec2(.5, 3.5));
    }
    if (id == 2) {
        d = seg(u, vec2(.5), vec2(.5, 2.5));
        return min(d, seg(u, vec2(.5,2.5), vec2(1.5, 2.5)));
    }
    if (id == 3) {
        d = seg(u, vec2(.5), vec2(2.5, .5));
        return min(d, seg(u, vec2(1.5, .5), vec2(1.5)));
    }
    if (id == 4) {
        d = seg(u, vec2(.5, 1.5), vec2(1.5));
        d = min(d, seg(u, vec2(1.5), vec2(1.5,.5)));
        return min(d, seg(u, vec2(1.5,.5), vec2(2.5,.5)));
    }
    return 1e5;
}

void mainImage( out vec4 o, vec2 u )
{
    vec2 R = iResolution.xy;
    float t = iTime,
          m = smoothstep(8., 11., t),
          s = mix(1., .15, m);

    u = 1. + (u+u-R)/R.y * s; 
    o = vec4(max(abs(u.x-1.),abs(u.y-1.)) < 1.);

    int id; 
    float i;
    for (; i++< min(6., t-1.);) sub(u, id);   

    o *= .6 + u.y/4.;
    o *= .67 + .33*cos(6.28*(vec4(0,1,2,0)/6. + float(id)/6.));
    //o.rgb = idToColor(id);

    float e = 1.4/iResolution.y * exp2(i-1.) * s;
    o = mix(o, vec4(0), .25*smoothstep(e, -e, dist(u, id) - .25));

    // Debug (check orientation/offset)
    // o *= .5+.5*step(length(.5*u-vec2(.1,.2)), .1);
}

// https://iquilezles.org/articles/distfunctions2d/
float seg( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}
